func generateParenthesis(_ n: Int) -> [String] {
    var result: [String] = []
    func build(_ s: String, _ open: Int, _ close: Int) {
        if s.count == 2 * n { result.append(s); return }
        if open < n { build(s + "(", open + 1, close) }
        if close < open { build(s + ")", open, close + 1) }
    }
    build("", 0, 0)
    return result
}
